#include <iostream>
using namespace std;

class Employe {
    protected:
        int base;
    public:
        Employe(int b) : base(b) {}
        virtual int salaire() const { return base; }
        virtual ~Employe() {}
};

class Manager : public Employe {
    private:
        int prime;
    public:
        Manager(int b, int p) : Employe(b), prime(p) {}
        int salaire() const override { return base + prime; }
};

void afficherSalaire(const Employe& e) {
    cout << e.salaire() << endl;
}

int main() {
    int b, p;
    cin >> b >> p;
    Employe e(b);
    Manager m(b, p);
    afficherSalaire(e);
    afficherSalaire(m);
    return 0;
}

